css:
/* ---- Shorts, everywhere they hide ---- */
ytd-reel-shelf-renderer,
ytm-reel-shelf-renderer,
ytd-rich-shelf-renderer[is-shorts],
ytd-rich-section-renderer:has(ytd-rich-shelf-renderer[is-shorts]),
grid-shelf-view-model:has(a[href*="/shorts/"]),
ytd-video-renderer:has(a[href*="/shorts/"]),
ytd-grid-video-renderer:has(a[href*="/shorts/"]),
ytd-rich-item-renderer:has(a[href*="/shorts/"]),
ytd-compact-video-renderer:has(a[href*="/shorts/"]),
ytd-guide-entry-renderer:has(a[title="Shorts"]),
ytd-mini-guide-entry-renderer[aria-label="Shorts"],
ytd-guide-entry-renderer:has(a[href="/shorts"]) {
  display: none !important;
}

/* ---- The home feed: nothing is recommended to you here ---- */
ytd-browse[page-subtype="home"] ytd-rich-grid-renderer,
ytd-browse[page-subtype="home"] #header.ytd-rich-grid-renderer,
ytd-browse[page-subtype="home"] ytd-feed-filter-chip-bar-renderer {
  display: none !important;
}

/* ---- Watch page: no sidebar, no comments, no upsell ---- */
#secondary.ytd-watch-flexy,
#related,
ytd-watch-next-secondary-results-renderer,
#comments,
ytd-comments,
ytd-merch-shelf-renderer,
ytd-ticket-shelf-renderer,
ytd-donation-shelf-renderer,
#donation-shelf,
ytd-engagement-panel-section-list-renderer[target-id*="shopping"],
ytd-watch-flexy #clarify-box {
  display: none !important;
}

/* Give the player the room the sidebar used to take. */
ytd-watch-flexy #columns.ytd-watch-flexy {
  max-width: 1400px;
  margin: 0 auto;
}
ytd-watch-flexy[flexy]:not([fullscreen]) #primary.ytd-watch-flexy {
  max-width: none !important;
  padding-right: 24px;
}

/* ---- In-player nags: end screens, cards, suggested actions, autoplay countdown ---- */
.ytp-endscreen-content,
.html5-endscreen,
.ytp-ce-element,
.ytp-ce-covering-overlay,
.ytp-suggested-action,
.ytp-pause-overlay,
.ytp-pause-overlay-container,
.ytp-autonav-endscreen-upnext-container,
.ytp-autonav-endscreen-countdown-overlay,
.iv-branding,
.ytp-cards-teaser {
  display: none !important;
}

/* ---- Ambient noise ---- */
#masthead-ad,
ytd-ad-slot-renderer,
ytd-in-feed-ad-layout-renderer,
ytd-banner-promo-renderer,
ytd-statement-banner-renderer,
tp-yt-paper-dialog:has(ytd-enforcement-message-view-model) {
  display: none !important;
}

/* ---- The empty home page, made deliberate rather than broken ---- */
#cb-clean-slate {
  max-width: 560px;
  margin: 12vh auto;
  padding: 0 24px;
  font-family: Roboto, system-ui, sans-serif;
  color: var(--yt-spec-text-primary, #0f0f0f);
}
#cb-clean-slate h1 { font-size: 22px; font-weight: 500; margin: 0 0 10px; }
#cb-clean-slate p { font-size: 14px; line-height: 1.6; opacity: .68; margin: 0 0 22px; }
#cb-clean-slate a {
  display: inline-block; margin-right: 10px; padding: 9px 16px;
  border: 1px solid var(--yt-spec-10-percent-layer, #0000001a);
  border-radius: 18px; text-decoration: none; font-size: 14px;
  color: inherit;
}
#cb-clean-slate a:hover { background: var(--yt-spec-badge-chip-background, #0000000d); }

js:
// Runs at document-start and on every SPA route change.
var o = options || {};

// 1. Shorts are just videos in a costume. Send them to the normal player.
if (o.shortsToWatch !== false && location.pathname.indexOf('/shorts/') === 0) {
  var id = location.pathname.split('/')[2];
  if (id) { location.replace('https://www.youtube.com/watch?v=' + id.split('?')[0]); return; }
}

// 2. The home page has nothing to show on purpose. Offer the doors worth walking through.
if (o.redirectHomeTo && (location.pathname === '/' || location.pathname === '')) {
  location.replace(o.redirectHomeTo);
  return;
}
if (location.pathname === '/' || location.pathname === '') {
  var paint = function () {
    if (document.getElementById('cb-clean-slate')) return;
    var host = document.querySelector('ytd-browse[page-subtype="home"]');
    if (!host) return;
    var box = document.createElement('div');
    box.id = 'cb-clean-slate';
    var h = document.createElement('h1'); h.textContent = 'Nothing is recommended to you here.';
    var p = document.createElement('p'); p.textContent = 'The home feed is off. Go where you meant to go.';
    box.appendChild(h); box.appendChild(p);
    [['Subscriptions', '/feed/subscriptions'], ['Watch later', '/playlist?list=WL'], ['History', '/feed/history']]
      .forEach(function (pair) {
        var a = document.createElement('a'); a.href = pair[1]; a.textContent = pair[0]; box.appendChild(a);
      });
    host.prepend(box);
  };
  // document.body does not exist at document-start, so poll instead of observing it.
  var tries = 0;
  var iv = setInterval(function () {
    paint();
    if (++tries > 40 || document.getElementById('cb-clean-slate')) clearInterval(iv);
  }, 300);
  document.addEventListener('DOMContentLoaded', paint);
}

// 3. Autoplay decides what you watch next. Turn it off and keep it off.
if (o.killAutoplay !== false) {
  var tries = 0;
  var off = setInterval(function () {
    if (++tries > 40) return clearInterval(off);
    var t = document.querySelector('.ytp-autonav-toggle-button[aria-checked="true"]');
    if (t) { t.click(); clearInterval(off); }
  }, 500);
}

// 4. Stop the player advancing on its own even if the toggle is missed.
if (o.killAutoplay !== false) {
  document.addEventListener('yt-autonav-pause-player-ended', function (e) { e.stopPropagation(); }, true);
}
